using System;
using Colossal.IO.AssetDatabase;

namespace BridgeBuilder.Bridges;

// Offline descriptor-only conversion preserves the original texture identities.
internal static class Draw01NativeMaterials
{
    // BEGIN generated native network sampling gate
    // Generated by EmitNetworkSampling.py from the complete fixed-base LOD graph.
    // The caller must also prove native NetPiece graph context; a reduced LOD is
    // a RenderPrefab, and must inherit that context rather than use its own type.
    internal static bool IsNativeNetwork(string render, int mesh, string sourceCid)
    {
        string? expected = (render, mesh) switch
        {
            ("DrawBridge01Bottom300cm Mesh", 0) => "16b28f9bc6abc54fd73acbdfa5f14978",
            ("DrawBridge01Bottom300cm_LOD1 Mesh", 0) => "4356073127d8273bdf532056e7249046",
            ("DrawBridge01Bottom300cm_LOD2 Mesh", 0) => "6bc4faa373df8dff10494f48bfe712b6",
            ("DrawBridge01BottomNode300cm Mesh", 0) => "8f424eb10e5caa7edce9770e4350d542",
            ("DrawBridge01BottomNode300cm_LOD1 Mesh", 0) => "94c792fc1bcd38993f9a799627500aad",
            ("DrawBridge01BottomNode300cm_LOD2 Mesh", 0) => "b396da47a5aeb3993c4f6c3c49ed182a",
            ("DrawBridge01BottomEdge350cm Mesh", 0) => "3527620a8e072cc2750c8a0f229d43ad",
            ("DrawBridge01BottomEdge350cm_LOD1 Mesh", 0) => "bdf23db4ff9b1860c6264159dd77caa8",
            ("DrawBridge01BottomEdge350cm_LOD2 Mesh", 0) => "d23c3e3a70ae885b3cdb5b581429fe5b",
            ("DrawBridge01BottomEdgeNode350cm Mesh", 0) => "bbdae65e0203aba4ba6e0a0ce9a93809",
            ("DrawBridge01BottomEdgeNode350cm_LOD1 Mesh", 0) => "6b740c6867f21e837b95b101b2313c1b",
            ("DrawBridge01BottomEdgeNode350cm_LOD2 Mesh", 0) => "1e4f265ef447732c2b1a0eca770fcba9",
            ("DrawBridge01BottomIntersectionMiddle200cm Mesh", 0) => "45f6fe14df0150267b86e281c8d17ec2",
            _ => null
        };
        return expected != null && sourceCid == expected;
    }
    // END generated native network sampling gate

    internal static string? ObjectDescriptor(string sourceCid) => sourceCid switch
    {
        "16b28f9bc6abc54fd73acbdfa5f14978" or "45f6fe14df0150267b86e281c8d17ec2"
            or "8f424eb10e5caa7edce9770e4350d542" => "1d6c92d008a952b1db4e1cc6cf7a1160",
        _ => null
    };

    internal static SurfaceAsset Resolve(SurfaceAsset original, Func<string, SurfaceAsset> load)
    {
        var cid = ObjectDescriptor(original.id.guid.ToString());
        if (cid == null) return original;
        original.LoadHeader();
        if (!original.isBuiltin || original.materialTemplateHash is not 17)
            throw new InvalidOperationException("Draw01 native network surface identity or template differs: " + original.id);
        var converted = load(cid);
        converted.LoadHeader();
        if (converted.id.guid.ToString() != cid || converted.materialTemplateHash is not 0 || converted.isVTMaterial)
            throw new InvalidOperationException("Draw01 native object descriptor differs: " + cid);
        return converted;
    }
}
